import{_ as i,o,c as a,a4 as n}from"./chunks/framework.CAYvAQr0.js";const h=JSON.parse('{"title":"Internationalization reference","description":"Public API, locale entry points, compatibility, and migration links for JSVision i18n.","frontmatter":{"title":"Internationalization reference","description":"Public API, locale entry points, compatibility, and migration links for JSVision i18n."},"headers":[],"relativePath":"reference/i18n.md","filePath":"reference/i18n.md"}'),t={name:"reference/i18n.md"};function r(l,e,c,s,d,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="internationalization-reference" tabindex="-1">Internationalization reference <a class="header-anchor" href="#internationalization-reference" aria-label="Permalink to &quot;Internationalization reference&quot;">​</a></h1><p>The generated <a href="/jsvision/pr-preview/pr-200/api/i18n/"><code>@jsvision/i18n</code> API</a> documents catalog authoring, translation, formatting, validation, diagnostics, and asynchronous sources. The default entry point is browser-safe; Node file loading is available from <a href="/jsvision/pr-preview/pr-200/api/i18n-node/"><code>@jsvision/i18n/node</code></a>.</p><p>Start with the <a href="/jsvision/pr-preview/pr-200/guide/i18n.html">internationalization guide</a> for a complete application workflow. The generated <a href="/jsvision/pr-preview/pr-200/reference/i18n-entry-points.html">entry-point index</a> links every Node and official locale subpath to its exported API symbol.</p><h2 id="official-locale-entry-points" tabindex="-1">Official locale entry points <a class="header-anchor" href="#official-locale-entry-points" aria-label="Permalink to &quot;Official locale entry points&quot;">​</a></h2><p>Framework packages publish one catalog from each explicit locale subpath:</p><ul><li><code>@jsvision/ui/locales/{locale}</code></li><li><code>@jsvision/forms/locales/{locale}</code></li><li><code>@jsvision/files/locales/{locale}</code></li><li><code>@jsvision/datagrid/locales/{locale}</code></li><li><code>@jsvision/code-editor/locales/{locale}</code></li></ul><p><code>{locale}</code> is one of <code>en</code>, <code>nl</code>, <code>de</code>, <code>fr</code>, <code>es</code>, <code>it</code>, <code>pt-PT</code>, <code>pl</code>, <code>ro</code>, or <code>sv</code>. Import only the locale your application requests; main package entry points do not include non-English catalogs.</p><h2 id="package-compatibility" tabindex="-1">Package compatibility <a class="header-anchor" href="#package-compatibility" aria-label="Permalink to &quot;Package compatibility&quot;">​</a></h2><p><code>@jsvision/i18n</code> is ESM-only, supports Node.js 22 or newer, has zero runtime dependencies, and uses the platform <code>Intl</code> implementation. It is owned and released by JSVision rather than wrapping <code>@blendsdk/i18n</code>.</p><p>The package <a href="https://github.com/blendsdk/jsvision/tree/master/packages/i18n" target="_blank" rel="noreferrer">README</a> covers BlendSDK migration and links the published third-party notice containing the upstream MIT attribution.</p>',10)])])}const m=i(t,[["render",r]]);export{h as __pageData,m as default};
